//! ML-KEM-512 instantiation (FIPS 203 Table 2).
//!
//! Parameters: k = 2, η₁ = 3, η₂ = 2, dᵤ = 10, dᵥ = 4.
//! Sizes: EK_LEN = 800, DK_LEN = 1632, CT_LEN = 768.
//!
//! Generated by the `ml_kem_impl!` macro.
//!
//! # CNSA gating
//!
//! ML-KEM-512 is **not** part of CNSA 2.0 (which mandates ML-KEM-1024)
//! and is **not** in the CNSA 1.0 suite either. The
//! `Service::MlKem512Keygen` / `Encaps` / `Decaps` variants are
//! permitted only under [`oxicrypt_module::AlgorithmProfile::Unrestricted`].
//! See `crates/oxicrypt-module/src/lib.rs` `is_cnsa1_allowed` and
//! `is_cnsa2_allowed`.

#![allow(
    clippy::indexing_slicing,
    clippy::arithmetic_side_effects,
    clippy::cast_possible_truncation,
    clippy::similar_names,
    dead_code
)]

crate::ml_kem_impl::ml_kem_impl! {
    k = 2;
    eta1 = 3;
    eta2 = 2;
    du = 10;
    dv = 4;
    svc_keygen = Service::MlKem512Keygen;
    svc_encaps = Service::MlKem512Encaps;
    svc_decaps = Service::MlKem512Decaps;
}

#[cfg(test)]
#[allow(
    clippy::unwrap_used,
    clippy::panic,
    clippy::indexing_slicing,
    clippy::arithmetic_side_effects
)]
mod tests {
    use super::*;

    #[test]
    fn round_trip_basic() {
        crate::test_support::start_module();
        let d = [0x42u8; 32];
        let z = [0x77u8; 32];
        let m = [0xABu8; 32];

        let (ek, dk) = keygen_internal(&d, &z).unwrap();
        let (k, ct) = encaps_internal(&ek, &m).unwrap();
        let k2 = decaps_internal(&dk, &ct).unwrap();
        assert_eq!(k, k2, "round-trip failed: shared secrets differ");
    }

    #[test]
    fn implicit_rejection_different_key() {
        crate::test_support::start_module();
        let d = [0x01u8; 32];
        let z = [0x02u8; 32];
        let m = [0x03u8; 32];

        let (ek, dk) = keygen_internal(&d, &z).unwrap();
        let (k, mut ct) = encaps_internal(&ek, &m).unwrap();
        ct[10] ^= 0xFF;
        let k_bad = decaps_internal(&dk, &ct).unwrap();
        assert_ne!(k, k_bad);
    }

    #[test]
    fn implicit_rejection_matches_j_z_c() {
        use oxicrypt_xof::Shake256;
        crate::test_support::start_module();

        let d = [0x05u8; 32];
        let z = [0x06u8; 32];
        let m = [0x07u8; 32];

        let (ek, dk) = keygen_internal(&d, &z).unwrap();
        let (_k, mut ct) = encaps_internal(&ek, &m).unwrap();
        ct[42] ^= 0xA5;

        let mut j = Shake256::new_internal().unwrap();
        j.update(&z);
        j.update(&ct);
        j.finalize();
        let mut expected_k_bar = [0u8; 32];
        j.squeeze(&mut expected_k_bar).unwrap();

        let actual = decaps_internal(&dk, &ct).unwrap();
        assert_eq!(
            actual, expected_k_bar,
            "implicit rejection key must equal J(z || c) byte-exactly per FIPS 203 §7.3"
        );
    }

    #[test]
    fn key_sizes_match_spec() {
        crate::test_support::start_module();
        // FIPS 203 Table 2: ML-KEM-512
        assert_eq!(EK_LEN, 800);
        assert_eq!(DK_LEN, 1632);
        assert_eq!(CT_LEN, 768);
        assert_eq!(SHARED_SECRET_LEN, 32);
    }

    #[test]
    fn parameter_constants_match_spec() {
        crate::test_support::start_module();
        assert_eq!(K, 2);
        assert_eq!(ETA1, 3);
        assert_eq!(ETA2, 2);
        assert_eq!(DU, 10);
        assert_eq!(DV, 4);
    }

    #[test]
    fn determinism() {
        crate::test_support::start_module();
        let (ek1, dk1) = keygen_internal(&[0x5au8; 32], &[0xa5u8; 32]).unwrap();
        let (ek2, dk2) = keygen_internal(&[0x5au8; 32], &[0xa5u8; 32]).unwrap();
        assert_eq!(ek1, ek2);
        assert_eq!(dk1, dk2);
    }
}
